import type { UIMessage } from "@plaisolutions/client"
import { getFilenameFromUrl } from "./internal/file-display"
import { getGeneratedFiles } from "./internal/generated-files"

/** A file generated by a tool, as the markdown of the answer may refer to it. */
export type GeneratedFileLinkTarget = {
  name: string
  url: string
  contentType?: string
}

type Range = readonly [start: number, end: number]

/** Nested links deeper than this are left as they are. */
const MAX_DEPTH = 8
/** The text of a link or image longer than this is not looked at. */
const MAX_LINK_TEXT = 1000
/** Same for a destination, so a half-written one costs little. */
const MAX_DESTINATION = 2000

const IMAGE_EXTENSIONS = new Set([
  "png",
  "jpg",
  "jpeg",
  "gif",
  "webp",
  "svg",
  "bmp",
  "avif",
])

const STRICT_SCHEMES = new Set(["sandbox", "file", "attachment"])
const SCHEME = /^([a-zA-Z][a-zA-Z0-9+.-]*):/
const BACKTICK_FENCE_OPEN = /^[ \t>]*(`{3,})([^\n]*)$/
const TILDE_FENCE_OPEN = /^[ \t>]*(~{3,})/
const BACKTICK_FENCE_CLOSE = /^[ \t>]*(`{3,})[ \t]*\r?$/
const TILDE_FENCE_CLOSE = /^[ \t>]*(~{3,})[ \t]*\r?$/

function lineEnd(src: string, from: number) {
  const newline = src.indexOf("\n", from)
  return newline === -1 ? src.length : newline
}

/** The end of the fence that opens at `from` (the whole text if it never closes). */
function fenceEnd(src: string, from: number): number | null {
  const first = src.slice(from, lineEnd(src, from))
  const backticks = BACKTICK_FENCE_OPEN.exec(first.replace(/\r$/, ""))
  // A line like ```code``` is inline code, not a fence.
  const opening =
    backticks && !backticks[2].includes("`")
      ? backticks[1]
      : (TILDE_FENCE_OPEN.exec(first)?.[1] ?? null)
  if (!opening) return null

  const close = opening[0] === "`" ? BACKTICK_FENCE_CLOSE : TILDE_FENCE_CLOSE
  let position = lineEnd(src, from) + 1
  while (position < src.length) {
    const end = lineEnd(src, position)
    const closing = close.exec(src.slice(position, end))?.[1]
    if (closing && closing.length >= opening.length) return end
    position = end + 1
  }
  return src.length
}

/** The end of the code span whose opening run of `length` backticks ends at `from`. */
function codeSpanEnd(src: string, from: number, length: number): number | null {
  let index = from
  while (index < src.length) {
    const char = src[index]
    if (char === "\n") {
      let next = index + 1
      while (src[next] === " " || src[next] === "\t") next++
      // A blank line ends the paragraph, and the span with it.
      if (next >= src.length || src[next] === "\n") return null
    }
    if (char === "`") {
      let end = index
      while (src[end] === "`") end++
      if (end - index === length) return end
      index = end
      continue
    }
    index++
  }
  return null
}

/** Fenced code blocks and code spans, which are never rewritten. */
function findProtectedRanges(src: string): Range[] {
  const ranges: Range[] = []
  let index = 0
  let atLineStart = true
  while (index < src.length) {
    if (atLineStart) {
      atLineStart = false
      const end = fenceEnd(src, index)
      if (end !== null) {
        ranges.push([index, end])
        index = end
        continue
      }
    }
    const char = src[index]
    if (char === "\n") {
      atLineStart = true
      index++
    } else if (char === "\\") {
      index += src[index + 1] === "\n" ? 1 : 2
    } else if (char === "`") {
      let runEnd = index
      while (src[runEnd] === "`") runEnd++
      const end = codeSpanEnd(src, runEnd, runEnd - index)
      if (end === null) {
        // No closing run: the backticks are literal, as the text may still be
        // arriving.
        index = runEnd
      } else {
        ranges.push([index, end])
        index = end
      }
    } else {
      index++
    }
  }
  return ranges
}

type Context = {
  src: string
  ranges: Range[]
  files: GeneratedFileLinkTarget[]
}

function rangeAt(context: Context, position: number): Range | undefined {
  const { ranges } = context
  let low = 0
  let high = ranges.length - 1
  while (low <= high) {
    const middle = (low + high) >> 1
    const range = ranges[middle]
    if (position < range[0]) high = middle - 1
    else if (position >= range[1]) low = middle + 1
    else return range
  }
  return undefined
}

type ParsedLink = {
  /** Index of the `[` that opens the text. */
  open: number
  textStart: number
  textEnd: number
  destination: string
  /** The title with the whitespace before it, or an empty string. */
  title: string
  end: number
}

function isBlank(char: string | undefined) {
  return char === " " || char === "\t" || char === "\n" || char === "\r"
}

function startsLikeGeneratedPath(text: string) {
  const scheme = SCHEME.exec(text)?.[1]?.toLowerCase()
  return (
    (scheme !== undefined && STRICT_SCHEMES.has(scheme)) ||
    text.startsWith("/mnt/")
  )
}

/**
 * Reads `[text](destination "title")` starting at the `[` at `open`. Returns
 * null when it is not (yet) a complete inline link, so text that is still
 * streaming is left as it is.
 */
function parseLink(
  context: Context,
  open: number,
  limit: number,
): ParsedLink | null {
  const { src } = context
  const textLimit = Math.min(limit, open + MAX_LINK_TEXT)
  let depth = 1
  let close = open + 1
  for (; close < textLimit; close++) {
    const char = src[close]
    if (char === "\\") {
      close++
      continue
    }
    const range = rangeAt(context, close)
    if (range) {
      close = range[1] - 1
      continue
    }
    if (char === "\n") {
      let next = close + 1
      while (src[next] === " " || src[next] === "\t") next++
      if (src[next] === "\n") return null
    } else if (char === "[") {
      depth++
    } else if (char === "]" && --depth === 0) {
      break
    }
  }
  if (close >= textLimit || src[close] !== "]" || src[close + 1] !== "(") {
    return null
  }

  let position = close + 2
  while (isBlank(src[position])) position++
  const destinationLimit = Math.min(limit, position + MAX_DESTINATION)
  let destination: string
  let destinationEnd: number

  if (src[position] === "<") {
    let end = position + 1
    while (end < destinationLimit && src[end] !== ">" && src[end] !== "\n") {
      end += src[end] === "\\" ? 2 : 1
    }
    if (src[end] !== ">") return null
    destination = src.slice(position + 1, end)
    destinationEnd = end + 1
  } else {
    let parentheses = 0
    let end = position
    for (; end < destinationLimit; end++) {
      const char = src[end]
      if (char === "\\") {
        end++
      } else if (isBlank(char)) {
        break
      } else if (char === "(") {
        parentheses++
      } else if (char === ")") {
        if (parentheses === 0) break
        parentheses--
      }
    }
    destination = src.slice(position, end)
    destinationEnd = end
  }

  const textStart = open + 1
  let end = destinationEnd
  while (isBlank(src[end])) end++
  let title = ""
  const quote = src[end]
  if (
    end > destinationEnd &&
    (quote === '"' || quote === "'" || quote === "(")
  ) {
    const closing = quote === "(" ? ")" : quote
    let titleEnd = end + 1
    while (titleEnd < destinationLimit && src[titleEnd] !== closing) {
      titleEnd += src[titleEnd] === "\\" ? 2 : 1
    }
    if (src[titleEnd] === closing) {
      title = src.slice(destinationEnd, titleEnd + 1)
      end = titleEnd + 1
      while (isBlank(src[end])) end++
    }
  }
  if (src[end] === ")") {
    return {
      open,
      textStart,
      textEnd: close,
      destination,
      title,
      end: end + 1,
    }
  }

  // The model often leaves the spaces of a file name unescaped, which is not
  // a link for markdown but is plainly meant as one. Accept it on one line.
  if (!startsLikeGeneratedPath(src.slice(position, position + 16))) return null
  let parentheses = 0
  for (let index = position; index < destinationLimit; index++) {
    const char = src[index]
    if (char === "\n") return null
    if (char === "(") {
      parentheses++
    } else if (char === ")") {
      if (parentheses === 0) {
        return {
          open,
          textStart,
          textEnd: close,
          destination: src.slice(position, index).trim(),
          title: "",
          end: index + 1,
        }
      }
      parentheses--
    }
  }
  return null
}

function decode(segment: string) {
  try {
    return decodeURIComponent(segment)
  } catch {
    return segment
  }
}

/** The file name a destination points to, or null when it names none. */
function fileNameOf(destination: string): string | null {
  const path = destination.replace(SCHEME, "").split(/[?#]/, 1)[0]
  const segment = path.split("/").pop() ?? ""
  const name = decode(segment).trim()
  return name && name !== "." && name !== ".." ? name : null
}

function fold(name: string) {
  return name.normalize("NFC").toLowerCase()
}

function findFile(files: GeneratedFileLinkTarget[], name: string) {
  const exact = files.find((file) => file.name === name)
  if (exact) return exact
  const folded = fold(name)
  return files.find((file) => fold(file.name) === folded)
}

type Decision =
  | { kind: "keep" }
  | { kind: "strip" }
  | { kind: "file"; file: GeneratedFileLinkTarget }

function decide(
  destination: string,
  files: GeneratedFileLinkTarget[],
): Decision {
  const target = destination.trim()
  if (!target) return { kind: "keep" }

  const scheme = SCHEME.exec(target)?.[1]?.toLowerCase()
  let strict = false
  if (scheme !== undefined) {
    if (!STRICT_SCHEMES.has(scheme)) return { kind: "keep" }
    strict = true
  } else if (target.startsWith("/mnt/")) {
    strict = true
  } else if (/^[/#?]/.test(target)) {
    return { kind: "keep" }
  }

  const name = fileNameOf(target)
  const file = name ? findFile(files, name) : undefined
  if (file) return { kind: "file", file }
  return strict ? { kind: "strip" } : { kind: "keep" }
}

function isImageFile(file: GeneratedFileLinkTarget) {
  const type = file.contentType?.toLowerCase().trim()
  if (type?.startsWith("image/")) return true
  if (type && type !== "application/octet-stream") return false
  const extension = file.name.split(".").pop()?.toLowerCase() ?? ""
  return IMAGE_EXTENSIONS.has(extension)
}

/** A destination that survives markdown parsing whatever the URL contains. */
function formatDestination(url: string) {
  const safe = url.replace(/[\s<>]/g, (char) => encodeURIComponent(char))
  return /[()]/.test(safe) ? `<${safe}>` : safe
}

function rewrite(
  context: Context,
  from: number,
  to: number,
  depth: number,
): string {
  const { src } = context
  let out = ""
  let copied = from
  let index = from

  while (index < to) {
    const char = src[index]
    if (char === "\\") {
      index += 2
      continue
    }
    const range = rangeAt(context, index)
    if (range) {
      index = range[1]
      continue
    }
    const isImage = char === "!" && src[index + 1] === "["
    if (char !== "[" && !isImage) {
      index++
      continue
    }

    const open = isImage ? index + 1 : index
    const link = depth < MAX_DEPTH ? parseLink(context, open, to) : null
    if (!link) {
      index = open + 1
      continue
    }

    const text = rewrite(context, link.textStart, link.textEnd, depth + 1)
    const decision = decide(link.destination, context.files)
    let replacement: string
    if (decision.kind === "keep") {
      replacement = `${src.slice(index, link.textStart)}${text}${src.slice(link.textEnd, link.end)}`
    } else if (decision.kind === "strip") {
      replacement = text
    } else {
      const { file } = decision
      const destination = `${formatDestination(file.url)}${link.title}`
      if (isImage && isImageFile(file)) {
        replacement = `![${text}](${destination})`
      } else if (isImage) {
        replacement = `[${text.trim() ? text : file.name}](${destination})`
      } else {
        replacement = `[${text}](${destination})`
      }
    }

    out += src.slice(copied, index) + replacement
    copied = link.end
    index = link.end
  }

  return out + src.slice(copied, to)
}

/**
 * Points the markdown links and images the model wrote to the files a tool
 * generated at the URL the file can really be downloaded from.
 *
 * The model often writes `![chart](sandbox:/mnt/data/chart.png)` or
 * `[report](/mnt/data/report.xlsx)`, paths that exist only in the sandbox, and
 * the renderer blocks them. A destination is looked at when it has the
 * `sandbox:`, `file:` or `attachment:` scheme, starts with `/mnt/` or is a
 * relative path; `http(s):`, `mailto:`, anchors and every other destination are
 * never touched. Its file name (without query or fragment, percent-decoded) is
 * matched to `files` by name, ignoring case if needed. A match becomes that
 * file's `url`: an image of a file that is not an image turns into a link. A
 * `sandbox:`, `file:`, `attachment:` or `/mnt/` destination with no matching file
 * is removed, leaving its text (the alt of an image), so no broken link is
 * left; a relative path with no match stays as written.
 *
 * Code blocks and code spans are not changed. Links that are not complete yet,
 * as in text that is still streaming, are left as they are, and the result can
 * go through the function again unchanged.
 */
export function resolveGeneratedFileLinks(
  markdown: string,
  files: readonly GeneratedFileLinkTarget[],
): string {
  // Cheap exit: every candidate is a link or an image.
  if (!markdown.includes("](")) return markdown
  const context: Context = {
    src: markdown,
    ranges: findProtectedRanges(markdown),
    files: files.filter((file) => file.name && file.url),
  }
  return rewrite(context, 0, markdown.length, 0)
}

/**
 * The files generated by the code_execution and office_documents tool calls of
 * a message, with the same `url` the cards use to download them.
 */
export function getMessageGeneratedFiles(
  message: Pick<UIMessage, "parts">,
): GeneratedFileLinkTarget[] {
  const targets: GeneratedFileLinkTarget[] = []
  for (const part of message.parts) {
    if (
      part.type !== "tool-call" ||
      (part.toolType !== "code_execution" &&
        part.toolType !== "office_documents")
    ) {
      continue
    }
    for (const file of getGeneratedFiles(part.metadata?.media_files)) {
      if (!file.url) continue
      const name =
        file.name ??
        getFilenameFromUrl(file.pathname ?? "") ??
        getFilenameFromUrl(file.url)
      if (!name) continue
      targets.push({ name, url: file.url, contentType: file.content_type })
    }
  }
  return targets
}
